CREATE TABLE inventory(svc TEXT, model TEXT, prompt_ver INT);
CREATE TABLE review(svc TEXT, model TEXT, prompt_ver INT, decided DATE);
INSERT INTO inventory VALUES ('상담챗봇','gpt-a-2026-09',7),('뉴스요약','sonnet-x',3),('회의록','local-8b',1);
INSERT INTO review VALUES ('상담챗봇','gpt-a-2026-06',5,'2026-07-01'),('뉴스요약','sonnet-x',3,'2026-10-02');

SELECT i.svc, i.model, i.prompt_ver,
       CASE WHEN r.svc IS NULL THEN '심의 기록 없음'
            WHEN r.model <> i.model OR r.prompt_ver <> i.prompt_ver THEN '재심의 필요'
            ELSE '정상' END AS 판정
FROM inventory i
LEFT JOIN (SELECT svc, model, prompt_ver, MAX(decided) d FROM review GROUP BY svc) r
       ON r.svc = i.svc
ORDER BY i.svc;

-- 뉴스요약 | sonnet-x      | 3 | 정상
-- 상담챗봇 | gpt-a-2026-09 | 7 | 재심의 필요
-- 회의록   | local-8b      | 1 | 심의 기록 없음
